import { useTranslation } from "react-i18next";

// Side-effect import: initialises i18next before the first render.
// Move this to the app entry point once one exists.
import "./i18n";

export default function App() {
  const { t } = useTranslation();
  const count = 3;
  const name = "Alex";

  return (
    <main>
      <nav>
        <a href="/">{t("nav.dashboard")}</a>
        <a href="/tasks">{t("nav.tasks")}</a>
      </nav>
      <h1>{t("home.greeting", { name })}</h1>
      <p>{t("home.tasksDue", { count })}</p>
      <button>{t("home.addTask")}</button>
      <label>
        <input type="checkbox" /> {t("home.emailUpdates")}
      </label>
    </main>
  );
}

import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import LanguageDetector from "i18next-browser-languagedetector";

import en from "./locales/en/translation.json";
import es from "./locales/es/translation.json";

// Locales whose scripts read right-to-left. Extend as translations are added.
const RTL_LANGUAGES = ["ar", "fa", "he", "ur"];

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      en: { translation: en },
      es: { translation: es },
    },
    fallbackLng: "en",
    // Treat "en-US" and "en-GB" as "en" so region variants resolve to a catalog.
    load: "languageOnly",
    interpolation: {
      // React escapes interpolated values already.
      escapeValue: false,
    },
  });

// Keep the document in sync so screen readers, hyphenation and font
// selection follow the active language.
function syncDocumentLanguage(language) {
  if (typeof document === "undefined") return;
  const base = language.split("-")[0];
  document.documentElement.lang = base;
  document.documentElement.dir = RTL_LANGUAGES.includes(base) ? "rtl" : "ltr";
}

syncDocumentLanguage(i18n.resolvedLanguage || i18n.language);
i18n.on("languageChanged", syncDocumentLanguage);

export default i18n;

